// modelo-formulario.js: GERADO por ferramentas/gerar_formulario_colaborador.py. Não edite à mão.
const MODELO_FORMULARIO = "<!doctype html>\n<html lang=\"pt-BR\" data-mode=\"colaborador\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Questionário</title>\n<style>\n/* estilo.css\n   Visual pensado para quem não tem familiaridade com tecnologia:\n   letras maiores, botões grandes, uma coisa por vez.\n   Verde = navegação e ações; amarelo = o que a pessoa preenche (como as células amarelas da planilha). */\n\n:root {\n  --bg: #EEF2EF; --surface: #FFFFFF; --ink: #142E27; --muted: #52665D; --line: #D2DCD5;\n  --green: #1C5843; --green-2: #2A7457; --green-soft: #E1EDE6; --green-line: #A9CBB8;\n  --tag: #EDB92E; --tag-soft: #FFF6D6; --tag-line: #E2C66F;\n  --alert: #A8392C; --alert-soft: #F9E5E0; --warn: #7A5700; --warn-soft: #FCF1D4;\n  --font: \"Avenir Next\", \"Avenir\", \"Segoe UI Variable Text\", \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  font-family: var(--font); color: var(--ink); background: var(--bg);\n  font-size: 16.5px; line-height: 1.55;\n}\n* { box-sizing: border-box }\nbody { margin: 0; min-height: 100vh }\nbutton, input, select, textarea { font: inherit; color: inherit }\n:focus-visible { outline: 3px solid var(--tag); outline-offset: 2px }\n[hidden] { display: none !important }\n.num { font-variant-numeric: tabular-nums }\n.muted { color: var(--muted) }\n.small { font-size: 14.5px }\n\n/* ---------- estrutura ---------- */\n.app { display: grid; grid-template-columns: 270px 1fr; min-height: 100vh }\n.side { background: var(--green); color: #EEF6F1; padding: 26px 16px 20px; display: flex; flex-direction: column; gap: 20px; position: sticky; top: 0; height: 100vh; overflow: auto }\n.brand { padding: 0 10px }\n.brand small { display: block; color: #B7D5C4; font-size: 13px }\n.brand strong { display: block; font-size: 20px; line-height: 1.25; margin-top: 3px }\n.nav { display: flex; flex-direction: column; gap: 3px }\n.nav button { all: unset; box-sizing: border-box; cursor: pointer; display: grid; grid-template-columns: 30px 1fr; align-items: center; gap: 11px; padding: 10px 12px; border-radius: 10px; color: #E6F1EA; font-weight: 600; line-height: 1.25 }\n.nav button:hover { background: rgba(255,255,255,.08) }\n.nav button:focus-visible { outline: 3px solid var(--tag) }\n.nav button[aria-current=\"page\"] { background: #F6F9F7; color: var(--green) }\n.nav .mark { width: 28px; height: 28px; border-radius: 50%; border: 2px solid currentColor; display: grid; place-items: center; font-size: 13px; font-weight: 800; position: relative }\n.nav .mark.done { background: var(--tag); border-color: var(--tag); color: var(--ink) }\n.nav .mark.pend::after { content: \"\"; position: absolute; top: -3px; right: -3px; width: 10px; height: 10px; border-radius: 50%; background: #F08A7A; border: 2px solid var(--green) }\n.nav button[aria-current=\"page\"] .mark.pend::after { border-color: #F6F9F7 }\n.nav .sep { height: 1px; background: rgba(255,255,255,.16); margin: 8px 6px }\n.side-foot { margin-top: auto; font-size: 14.5px }\n.side-foot details summary { cursor: pointer; padding: 8px 12px; border-radius: 8px; color: #D9EBE0; list-style: none }\n.side-foot details summary::-webkit-details-marker { display: none }\n.side-foot details summary::before { content: \"⋯  \" }\n.side-foot details summary:hover { background: rgba(255,255,255,.08) }\n.side-foot .menu { display: flex; flex-direction: column; gap: 2px; padding: 4px 0 0 }\n.side-foot .menu button { all: unset; cursor: pointer; padding: 7px 12px; border-radius: 8px; color: #E6F1EA }\n.side-foot .menu button:hover { background: rgba(255,255,255,.08) }\n.side-foot .menu button:focus-visible { outline: 3px solid var(--tag) }\n.saved { padding: 8px 12px 0; color: #A9C9B8; font-size: 13px }\n\nmain { padding: 36px 44px 90px; width: 100%; max-width: 1100px; min-width: 0 }\nmain:focus { outline: none }\n.head { margin-bottom: 24px; max-width: 760px }\n.head h1 { font-size: 31px; line-height: 1.15; margin: 0 0 8px; letter-spacing: -.02em }\n.head p { margin: 0; color: var(--muted); font-size: 17px }\nh2 { font-size: 20px; margin: 0 0 6px; letter-spacing: -.01em }\nh3 { font-size: 17px; margin: 0 0 4px }\n.lead { color: var(--muted); margin: 0 0 16px; max-width: 68ch }\n.block { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 24px 26px; margin: 0 0 18px }\n.section-title { margin: 30px 0 12px }\n\n/* ---------- botões ---------- */\n.btn { border: 0; border-radius: 10px; padding: 12px 20px; min-height: 46px; font-weight: 700; cursor: pointer; background: var(--green); color: #fff; display: inline-flex; align-items: center; gap: 8px; text-decoration: none }\n.btn:hover { background: var(--green-2) }\n.btn.big { font-size: 18px; padding: 15px 26px; min-height: 56px }\n.btn.light { background: var(--surface); color: var(--green); border: 2px solid var(--green-line) }\n.btn.light:hover { background: var(--green-soft); border-color: var(--green) }\n.btn.quiet { background: transparent; color: var(--green); padding: 8px 12px; min-height: 40px; text-decoration: underline; text-underline-offset: 3px }\n.btn.quiet:hover { background: var(--green-soft) }\n.btn.danger { background: transparent; color: var(--alert); padding: 8px 12px; min-height: 40px }\n.btn.danger:hover { background: var(--alert-soft) }\n.actions { display: flex; gap: 10px; flex-wrap: wrap; align-items: center }\n\n/* ---------- campos ---------- */\n.field { margin: 0 0 20px }\n.field > label, .field > .q { display: block; font-weight: 700; margin-bottom: 7px; font-size: 16.5px }\n.field .hint { display: block; color: var(--muted); font-size: 14.5px; margin: -3px 0 8px; font-weight: 400 }\n.in { width: 100%; max-width: 460px; padding: 11px 13px; border-radius: 9px; background: var(--tag-soft); border: 1.5px solid var(--tag-line); border-bottom: 3px solid var(--tag) }\n.in:hover { border-color: var(--tag) }\n.in.bad, .bad .in { background: var(--alert-soft); border-color: #E2A79D; border-bottom-color: var(--alert) }\nselect.in { cursor: pointer }\ntextarea.in { min-height: 70px; resize: vertical }\n\n/* escolhas em botões (rádio) */\n.choices { display: flex; flex-wrap: wrap; gap: 8px }\n.choices.cols { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)) }\n.choice { position: relative }\n.choice input { position: absolute; opacity: 0; inset: 0; margin: 0; pointer-events: none }\n.choice span { display: block; padding: 10px 15px; border-radius: 10px; background: var(--tag-soft); border: 1.5px solid var(--tag-line); cursor: pointer; font-weight: 650; min-height: 46px; line-height: 1.3 }\n.choice span small { display: block; font-weight: 400; color: var(--muted); font-size: 13.5px; margin-top: 2px }\n.choice:hover span { border-color: var(--tag) }\n.choice input:checked + span { background: var(--green); border-color: var(--green); color: #fff }\n.choice input:checked + span small { color: #D5EADF }\n.choice input:checked + span::before { content: \"✓ \" }\n.choice input:focus-visible + span { outline: 3px solid var(--tag); outline-offset: 2px }\n.field.missing .choices .choice span { border-color: #E2A79D; background: var(--alert-soft) }\n.field.missing > .q::after { content: \"  ← falta responder\"; color: var(--alert); font-weight: 700; font-size: 14px }\n\n/* contador com − e + */\n.stepper { display: inline-flex; align-items: stretch; border-radius: 10px; overflow: hidden; border: 1.5px solid var(--tag-line); border-bottom: 3px solid var(--tag); background: var(--tag-soft) }\n.stepper button { border: 0; background: transparent; width: 50px; font-size: 22px; font-weight: 700; cursor: pointer; color: var(--green) }\n.stepper button:hover { background: #FBEBB4 }\n.stepper input { border: 0; background: transparent; width: 110px; text-align: center; font-weight: 700; font-size: 18px; padding: 10px 0 }\n.stepper .unit { align-self: center; padding-right: 14px; color: var(--muted); font-size: 14.5px }\n\n/* ---------- cartões ---------- */\n.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px }\n.card { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 20px 22px; display: flex; flex-direction: column; gap: 10px }\n.card.warn { border-color: #E9B7AE; box-shadow: inset 4px 0 0 var(--alert) }\n.card h3 { font-size: 19px; margin: 0 }\n.card .role { color: var(--muted); margin-top: -6px }\n.card .card-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: auto; padding-top: 6px }\n.status { display: flex; gap: 8px; align-items: flex-start; font-size: 15px; font-weight: 600 }\n.status::before { content: \"\"; flex: 0 0 10px; height: 10px; border-radius: 50%; margin-top: 7px; background: currentColor }\n.status.ok { color: var(--green) }\n.status.err { color: var(--alert) }\n.status.info { color: var(--warn) }\n.pill { display: inline-block; font-size: 13.5px; font-weight: 700; padding: 3px 10px; border-radius: 20px; background: var(--green-soft); color: var(--green) }\n.pill.yellow { background: var(--tag-soft); color: var(--warn); border: 1px solid var(--tag-line) }\n.skills { display: grid; gap: 5px; font-size: 14.5px }\n.skills div { display: flex; justify-content: space-between; gap: 10px }\n.dots { letter-spacing: 3px; color: var(--green); white-space: nowrap }\n.dots i { font-style: normal; color: #C9D6CE }\n.empty { text-align: center; padding: 40px 24px; color: var(--muted); background: var(--surface); border: 2px dashed var(--line); border-radius: 14px }\n.empty p { margin: 0 0 16px; font-size: 17px }\n.chips { display: flex; flex-wrap: wrap; gap: 8px }\n.chips button { border: 1.5px dashed var(--green-line); background: var(--surface); color: var(--green); border-radius: 20px; padding: 7px 14px; cursor: pointer; font-weight: 600 }\n.chips button:hover { background: var(--green-soft); border-style: solid }\n\n/* ---------- início ---------- */\n.journey { list-style: none; padding: 0; margin: 0; display: grid; gap: 12px }\n.journey li { display: grid; grid-template-columns: 52px 1fr auto; gap: 16px; align-items: center; background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 16px 20px }\n.journey li.next { border: 2px solid var(--green); box-shadow: 0 4px 16px rgba(28,88,67,.12) }\n.journey .mark { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; font-weight: 800; font-size: 18px; border: 2px solid var(--green-line); color: var(--green) }\n.journey .mark.done { background: var(--tag); border-color: var(--tag); color: var(--ink) }\n.journey h3 { margin: 0 }\n.journey p { margin: 2px 0 0; color: var(--muted); font-size: 15px }\n.journey .state { font-size: 14.5px; font-weight: 700; margin-top: 4px }\n.journey .state.err { color: var(--alert) }\n.journey .state.ok { color: var(--green) }\n.hello { font-size: 18px; max-width: 64ch; margin: 0 0 22px }\n\n/* ---------- avisos ---------- */\n.banner { display: flex; gap: 14px; align-items: flex-start; border-radius: 12px; padding: 15px 18px; margin: 0 0 20px; font-weight: 600; font-size: 16.5px }\n.banner.ok { background: var(--green-soft); color: var(--green) }\n.banner.aviso { background: var(--warn-soft); color: var(--warn) }\n.banner.erro { background: var(--alert-soft); color: var(--alert) }\n.banner .ico { font-size: 20px; line-height: 1.2 }\n.banner .more { font-weight: 500; margin-top: 6px; display: flex; flex-wrap: wrap; gap: 6px 14px }\n.banner a, .banner button.link { color: inherit; font-weight: 700; background: none; border: 0; padding: 0; cursor: pointer; text-decoration: underline; text-underline-offset: 3px }\n.example-bar { display: flex; flex-wrap: wrap; gap: 12px 18px; align-items: center; justify-content: space-between; background: var(--tag-soft); border: 1.5px solid var(--tag-line); border-radius: 12px; padding: 14px 18px; margin: 0 0 22px }\n\n/* ---------- plano ---------- */\n.capacity { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 22px 24px; margin-bottom: 22px }\n.cap-row { display: grid; grid-template-columns: 220px 1fr 140px; gap: 16px; align-items: center; margin: 12px 0 }\n.cap-row .t { font-weight: 700; font-size: 15px }\n.cap-row .v { font-size: 15px; color: var(--muted); text-align: right }\n.cap-row .v b { color: var(--ink) }\n.bar { display: flex; height: 48px; border-radius: 9px; overflow: hidden; background: repeating-linear-gradient(135deg, #F1F4F2 0 7px, #E5EBE7 7px 14px); border: 1px solid var(--line) }\n.bar .seg { display: flex; flex-direction: column; justify-content: center; padding: 0 10px; color: #fff; font-size: 13px; line-height: 1.25; overflow: hidden; white-space: nowrap; border-right: 2px solid var(--surface); min-width: 0 }\n.bar .seg.c0 { background: var(--green) } .bar .seg.c1 { background: var(--green-2) } .bar .seg.c2 { background: #4E8F72 } .bar .seg.c3 { background: #3F6F5D }\n.bar .seg.cult { background: var(--tag); color: var(--ink) }\n.bar.thin { height: 16px }\n.slots { display: flex; gap: 7px; flex-wrap: wrap }\n.slots i { width: 34px; height: 26px; border-radius: 6px; border: 2px solid var(--green); background: var(--surface) }\n.slots i.on { background: var(--green) }\n.slots i.cult { background: var(--tag); border-color: var(--tag) }\n.facts { display: flex; gap: 30px; flex-wrap: wrap; margin-bottom: 8px }\n.facts div { color: var(--muted); font-size: 15px }\n.facts b { display: block; color: var(--ink); font-size: 22px }\n.action { display: grid; grid-template-columns: 46px 1fr; gap: 14px; background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 18px 22px; margin: 0 0 12px }\n.action .n { width: 40px; height: 40px; border-radius: 50%; background: var(--green); color: #fff; display: grid; place-items: center; font-weight: 800; font-size: 17px }\n.action.later .n { background: #C9D6CE; color: var(--ink) }\n.action.prep .n { background: var(--tag); color: var(--ink) }\n.action h3 { font-size: 18px; margin: 0 }\n.action .what { font-weight: 700; color: var(--green); margin: 2px 0 }\n.action .desc { color: var(--muted); margin: 0 0 8px; font-size: 15px }\n.action dl { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 6px 18px; margin: 8px 0 10px; font-size: 15px }\n.action dt { color: var(--muted); font-size: 13.5px }\n.action dd { margin: 0; font-weight: 650 }\n.action .next { background: var(--green-soft); border-radius: 9px; padding: 9px 12px; font-size: 15px; margin: 4px 0 10px }\n.action.later .next { background: var(--warn-soft); color: var(--warn); font-weight: 650 }\n.action .extra { font-size: 14.5px; color: var(--warn); margin: 0 0 8px }\n.action .choices .choice span { min-height: 40px; padding: 7px 13px; font-size: 15px }\n\n/* ---------- janelas ---------- */\ndialog { border: 0; border-radius: 16px; padding: 0; width: min(760px, calc(100vw - 24px)); max-height: calc(100vh - 32px); color: var(--ink); box-shadow: 0 20px 60px rgba(10,30,24,.35) }\ndialog::backdrop { background: rgba(14,36,29,.55) }\n.dlg { display: flex; flex-direction: column; max-height: calc(100vh - 32px) }\n.dlg-head { padding: 22px 28px 12px; border-bottom: 1px solid var(--line); display: flex; justify-content: space-between; gap: 16px; align-items: flex-start }\n.dlg-head h2 { font-size: 23px; margin: 0 }\n.dlg-head p { margin: 4px 0 0; color: var(--muted) }\n.dlg-x { border: 0; background: transparent; font-size: 28px; line-height: 1; cursor: pointer; color: var(--muted); padding: 2px 8px; border-radius: 8px }\n.dlg-x:hover { background: var(--bg) }\n.dlg-body { padding: 22px 28px; overflow: auto }\n.dlg-foot { padding: 16px 28px; border-top: 1px solid var(--line); display: flex; gap: 10px; justify-content: flex-end; flex-wrap: wrap; background: #F7FAF8; border-radius: 0 0 16px 16px }\n.dlg-msg { color: var(--alert); font-weight: 700; margin-right: auto; align-self: center }\n.group-title { font-size: 15px; font-weight: 800; color: var(--green); margin: 8px 0 14px; padding-top: 14px; border-top: 1px dashed var(--line) }\n.group-title:first-child { border-top: 0; padding-top: 0 }\n.preview { background: var(--green-soft); border-radius: 10px; padding: 12px 15px; margin: 4px 0 18px; font-size: 15.5px }\n\n/* ---------- questionário ---------- */\n.privacy { border-left: 4px solid var(--green-line); background: var(--green-soft); padding: 12px 16px; border-radius: 0 10px 10px 0; font-size: 15px; margin: 0 0 20px; max-width: 72ch }\n.result-band { font-size: 26px; font-weight: 800; margin: 4px 0 }\n.solo { max-width: 820px; margin: 0 auto; padding: 40px 22px 80px }\n.solo .block { padding: 26px 28px }\n\n.toast { position: fixed; right: 22px; bottom: 22px; background: var(--ink); color: #fff; padding: 13px 18px; border-radius: 10px; font-size: 15.5px; box-shadow: 0 6px 20px rgba(21,48,42,.3); max-width: 420px; opacity: 0; transform: translateY(8px); transition: .2s; pointer-events: none; z-index: 20 }\n.toast.show { opacity: 1; transform: none }\n\n/* ---------- avançado ---------- */\ndetails.advanced { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 0; margin: 0 0 18px }\ndetails.advanced > summary { cursor: pointer; padding: 18px 26px; font-weight: 700; color: var(--green) }\ndetails.advanced[open] > summary { border-bottom: 1px solid var(--line) }\ndetails.advanced .inner { padding: 20px 26px }\ntable { border-collapse: collapse; width: 100%; font-size: 15px }\nth, td { padding: 8px; text-align: left; border-bottom: 1px solid #E5EBE7; vertical-align: middle }\nth { font-size: 13.5px; color: var(--muted) }\ntd .in { max-width: 120px; padding: 7px 9px }\n.scroll { overflow-x: auto }\n.help-list { margin: 0; padding-left: 20px }\n.help-list li { margin: 6px 0 }\n\n@media (max-width: 900px) {\n  .app { grid-template-columns: 1fr }\n  .side { position: static; height: auto; padding: 14px 12px; gap: 10px }\n  .brand { padding: 0 4px }\n  .nav { flex-direction: row; overflow-x: auto; gap: 4px; padding-bottom: 4px }\n  .nav button { grid-template-columns: 28px auto; white-space: nowrap }\n  .nav .sep { display: none }\n  .side-foot { margin-top: 0 }\n  main { padding: 22px 16px 70px }\n  .head h1 { font-size: 26px }\n  .journey li { grid-template-columns: 44px 1fr; }\n  .journey li .btn { grid-column: 1 / -1 }\n  .cap-row { grid-template-columns: 1fr; gap: 6px }\n  .cap-row .v { text-align: left }\n  .action { grid-template-columns: 1fr }\n  dialog { width: 100vw; max-height: 100vh; border-radius: 0; margin: 0 }\n  .dlg { max-height: 100vh }\n  .dlg-body, .dlg-head, .dlg-foot { padding-left: 18px; padding-right: 18px }\n}\n@media (prefers-reduced-motion: reduce) { * { transition: none !important; scroll-behavior: auto !important } }\n@media print {\n  body { background: #fff; font-size: 12px }\n  .side, .no-print, .btn, .actions, .choices, .toast { display: none !important }\n  .app { display: block }\n  main { padding: 0; max-width: none }\n  .action, .capacity, .block { break-inside: avoid; border: 1px solid #bbb }\n  .bar .seg, .slots i, .action .n { -webkit-print-color-adjust: exact; print-color-adjust: exact }\n}\n\n/* usado na página de testes */\n.chip { display: inline-block; font-size: 13px; font-weight: 700; padding: 2px 9px; border-radius: 20px }\n.chip.ok { background: var(--green-soft); color: var(--green) }\n.chip.err { background: var(--alert-soft); color: var(--alert) }\n</style>\n</head>\n<body>\n<div id=\"root\"></div>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n<script>\n// motor.js\n// Toda a lógica de cálculo. Versão 2 das regras: parte das fórmulas da planilha Matriz_Transicao_IA_v1.xlsx\n// e muda o que os testes de sentido apontaram (ver diagnostico.txt, Parte 3). Mudanças marcadas com [v2-n].\n// Não depende da interface: pode ser testado sozinho (veja testes/Executar_Testes.html).\n\nconst COMPS = [\n  ['C01', 'Usar IA e formular instruções', 'Digitais e de dados'],\n  ['C02', 'Conferir resultados e decidir', 'Cognitivas complexas'],\n  ['C03', 'Organizar dados e estoque', 'Digitais e de dados'],\n  ['C04', 'Atender com empatia e adaptar-se', 'Socioemocionais e adaptação'],\n  ['C05', 'Revisar e criar conteúdo', 'Cognitivas complexas'],\n  ['C06', 'Conduzir mudança e orientar equipe', 'Liderança']\n];\n// [v2-7] EXT (apoio externo) e [v2-8] MAT (maturidade digital da loja) entram no catálogo\nconst INTERV_CODES = ['CULT', 'PARES', 'EXP', 'TUTOR', 'RED', 'PRES', 'EXT', 'MAT'];\nconst TASK_Q = ['ativa', 'q1', 'q2', 'q3', 'q4', 'q5', 'r1', 'r2', 'r3'];\nconst ANDAMENTOS = ['Não iniciada', 'Em andamento', 'Concluída'];\nconst PRONTIDOES = ['Baixa', 'Moderada', 'Alta'];\nconst MATURIDADE_ITENS = ['Registros digitais organizados', 'Equipamentos e acesso disponíveis', 'Rotinas de conferência de dados', 'Apoio à aprendizagem na rotina'];\nconst EPS = 1e-9;\n\nconst isNum = x => typeof x === 'number' && Number.isFinite(x);\nconst filled = x => x !== undefined && x !== null && String(x).trim() !== '';\nconst up = s => String(s).trim().toUpperCase();\n// [v2-13] compara códigos pelo número (D9 < D10 < D100), não pelo texto\nconst idNum = id => { const m = /(\\d+)/.exec(String(id || '')); return m ? +m[1] : 0; };\nconst cmpId = (a, b) => idNum(a) - idNum(b) || (up(a) < up(b) ? -1 : up(a) > up(b) ? 1 : 0);\n\n// ---------- dados de exemplo (Mercado Aurora, fictício) ----------\nfunction exemploAurora() {\n  return {\n    versao: '2.0',\n    negocio: {\n      loja: 'Mercado Aurora (simulado)', segmento: 'Minimercado de bairro', dataBase: '2026-09-22',\n      horas: 3, orcamento: 80, maxAcoes: 3,\n      maturidade: [1, 1, 2, 2],\n      riscoAlto: 2, prontBaixa: 1, prontAlta: 2, presHoras: 0.5,\n      maxAprendizes: 2,            // [v2-9] aprendizes simultâneos por colega\n      cultGrupo: 'Sim',            // [v2-10] preparação cultural em grupo\n      cultHoraExtra: 0.25,         // [v2-10] horas a mais por pessoa extra no grupo\n      matAndamento: 'Não iniciada',\n      intervencoes: {\n        CULT: { nome: 'Preparação cultural', horas: 1, semanas: 2, custo: 0, participantes: 'Pessoa(s) + colega', compartilhado: false },\n        PARES: { nome: 'Aprendizagem entre pares', horas: 1, semanas: 4, custo: 0, participantes: 'Pessoa + colega', compartilhado: false },\n        EXP: { nome: 'Experimentação assistida', horas: 1, semanas: 8, custo: 0, participantes: 'Pessoa', compartilhado: false },\n        TUTOR: { nome: 'Mentoria por IA', horas: 0.5, semanas: 4, custo: 0, participantes: 'Pessoa', compartilhado: false },\n        RED: { nome: 'Redesenho gradual', horas: 0.5, semanas: 8, custo: 0, participantes: 'Pessoa', compartilhado: false },\n        PRES: { nome: 'Preservação de competências', horas: 0, semanas: 4, custo: 0, participantes: 'Pessoa + colega', compartilhado: false },\n        EXT: { nome: 'Apoio externo', horas: 1, semanas: 4, custo: 0, participantes: 'Pessoa + apoio externo', compartilhado: false },\n        MAT: { nome: 'Elevar maturidade digital', horas: 1, semanas: 8, custo: 0, participantes: 'Gestor', compartilhado: false }\n      }\n    },\n    equipe: [\n      { id: 'E01', nome: 'Helena', funcao: 'Proprietária-gestora', gestor: 'Sim', prontidao: 'Alta', c: [1, 2, 2, 3, 1, 1], obs: '', prep: '' },\n      { id: 'E02', nome: 'Bruno', funcao: 'Atendimento e vendas', gestor: 'Não', prontidao: 'Baixa', c: [0, 1, 1, 3, 1, 0], obs: '', prep: '' },\n      { id: 'E03', nome: 'Carla', funcao: 'Estoque e reposição', gestor: 'Não', prontidao: 'Moderada', c: [1, 2, 1, 2, 0, 0], obs: '', prep: '' },\n      { id: 'E04', nome: 'Diego', funcao: 'Marketing e mídias', gestor: 'Não', prontidao: 'Alta', c: [2, 2, 3, 2, 1, 1], obs: '', prep: '' },\n      { id: 'E05', nome: 'Elisa', funcao: 'Caixa e retaguarda', gestor: 'Não', prontidao: 'Alta', c: [1, 3, 2, 3, 0, 0], obs: '', prep: '' }\n    ],\n    tarefas: [\n      ['T01', 'Responder dúvidas no WhatsApp', 'Sim', 'Não', 'Não', 'Sim', 'Sim', 'Não', 'Sim', 'Sim', 'Não'],\n      ['T02', 'Planejar pedido ao fornecedor', 'Sim', 'Não', 'Não', 'Sim', 'Sim', 'Não', 'Sim', 'Sim', 'Sim'],\n      ['T03', 'Criar conteúdo para redes sociais', 'Sim', 'Não', 'Não', 'Não', 'Não', 'Sim', 'Não', 'Sim', 'Sim'],\n      ['T04', 'Conferir lançamentos do caixa', 'Sim', 'Não', 'Não', 'Sim', 'Sim', 'Não', 'Não', 'Sim', 'Sim'],\n      ['T05', 'Negociar reclamação sensível', 'Sim', 'Não', 'Sim', 'Não', 'Não', 'Não', 'Sim', 'Sim', 'Sim'],\n      ['T06', 'Analisar indicadores de vendas', 'Sim', 'Não', 'Não', 'Não', 'Não', 'Não', 'Não', 'Sim', 'Sim'],\n      ['T07', 'Preparar roteiro de capacitação', 'Sim', 'Não', 'Não', 'Não', 'Não', 'Sim', 'Não', 'Não', 'Sim'],\n      ['T08', 'Conferir produtos na prateleira', 'Sim', 'Sim', 'Não', 'Sim', 'Não', 'Não', 'Não', 'Sim', 'Sim']\n    ].map(r => { const t = { id: r[0], nome: r[1] }; TASK_Q.forEach((k, i) => t[k] = r[i + 2]); return t; }),\n    diagnosticos: [\n      ['D01', 'E01', 'T06', 'C01', 3, 3, 'Entrada simulada'],\n      ['D02', 'E02', 'T01', 'C01', 2, 3, 'Entrada simulada'],\n      ['D03', 'E03', 'T02', 'C03', 3, 3, 'Entrada simulada'],\n      ['D04', 'E04', 'T03', 'C05', 2, 2, 'Entrada simulada'],\n      ['D05', 'E05', 'T04', 'C01', 2, 2, 'Entrada simulada'],\n      ['D06', 'E01', 'T07', 'C06', 2, 3, 'Entrada simulada'],\n      ['D07', 'E01', 'T05', 'C04', 3, 3, 'Tarefa humana'],\n      ['D08', 'E05', 'T02', 'C02', 2, 3, 'Sem lacuna, com preservação']\n    ].map(r => ({ id: r[0], pessoa: r[1], tarefa: r[2], comp: r[3], meta: r[4], crit: r[5], andamento: 'Não iniciada', evidencia: r[6] }))\n  };\n}\n\nfunction estadoVazio() {\n  const s = exemploAurora();\n  s.negocio.loja = ''; s.negocio.segmento = '';\n  s.negocio.dataBase = new Date().toISOString().slice(0, 10);\n  s.equipe = []; s.tarefas = []; s.diagnosticos = [];\n  return s;\n}\n\nfunction addDays(iso, n) {\n  if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(iso || '')) return null;\n  const [y, m, d] = iso.split('-').map(Number);\n  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);\n}\n\n// ---------- Negocio!B46: validação dos parâmetros ----------\nfunction validarNegocio(N) {\n  const e = [];\n  const base = [N.horas, N.orcamento, N.maxAcoes];\n  if (!base.every(isNum)) e.push('Preencha horas semanais, orçamento e máximo de ações.');\n  else {\n    if (Math.min(...base) < 0) e.push('Horas, orçamento e máximo de ações não podem ser negativos.');\n    if (!Number.isInteger(N.maxAcoes)) e.push('O máximo de ações simultâneas deve ser um número inteiro.');\n  }\n  if (!N.maturidade.every(isNum)) e.push('Responda os quatro itens de maturidade digital.');\n  else if (N.maturidade.some(x => x < 0 || x > 3)) e.push('Maturidade digital vai de 0 a 3.');\n  if (![N.riscoAlto, N.prontBaixa, N.prontAlta, N.presHoras].every(isNum)) e.push('Preencha os limites de risco, prontidão e preservação.');\n  else {\n    if (N.riscoAlto < 1 || N.riscoAlto > 3) e.push('O limite de risco alto deve ficar entre 1 e 3.');\n    if (N.prontBaixa < 0) e.push('O limite de prontidão baixa não pode ser negativo.');\n    if (N.prontAlta <= N.prontBaixa) e.push('O limite de prontidão alta deve ser maior que o de prontidão baixa.');\n    if (N.prontAlta > 3) e.push('O limite de prontidão alta não pode passar de 3.');\n    if (N.presHoras < 0) e.push('As horas de preservação não podem ser negativas.');\n  }\n  if (!isNum(N.maxAprendizes) || !Number.isInteger(N.maxAprendizes) || N.maxAprendizes < 1) e.push('Aprendizes por colega: número inteiro a partir de 1.');\n  if (N.cultGrupo !== 'Sim' && N.cultGrupo !== 'Não') e.push('Indique se a preparação cultural é feita em grupo.');\n  if (!isNum(N.cultHoraExtra) || N.cultHoraExtra < 0) e.push('Horas extras por pessoa na preparação em grupo: número a partir de 0.');\n  for (const k of INTERV_CODES) {\n    const it = N.intervencoes[k];\n    if (![it.horas, it.semanas, it.custo].every(isNum)) { e.push(`Preencha horas, semanas e custo de “${it.nome}”.`); continue; }\n    if (Math.min(it.horas, it.semanas, it.custo) < 0) e.push(`“${it.nome}” tem valor negativo.`);\n    if (it.semanas < 1 || it.semanas > 12) e.push(`A duração de “${it.nome}” deve ficar entre 1 e 12 semanas.`);\n  }\n  return e;\n}\n\n// [v2-6] intervenções compatíveis para uma necessidade técnica (pessoa × competência).\n// Prontidão moderada prefere ações acompanhadas; mentoria por IA só para prontidão alta e quem já usa IA (C01 ≥ 1).\n// [v2-7] apoio externo é o último recurso: só quando nenhuma opção interna é compatível.\nconst ORDEM_EMPATE = ['PARES', 'RED', 'EXP', 'TUTOR'];\nfunction escolherIntervencao(a, IV, semColega) {\n  const W = semColega ? 0 : a.colegas.length, U = a.lacuna;\n  const compat = [];\n  if (W > 0) compat.push('PARES');\n  if (a.automacao) compat.push('RED');\n  if (U >= 2 || a.prontidao === 'Moderada') compat.push('EXP');\n  if ((U === 1 || W === 0) && a.prontidao === 'Alta' && a.nivelIA >= 1) compat.push('TUTOR');\n  if (!compat.length) return 'EXT';\n  const min = Math.min(...compat.map(k => IV[k].custo));\n  return ORDEM_EMPATE.find(k => compat.includes(k) && IV[k].custo === min);\n}\n\n// ---------- cálculo completo: Equipe, Tarefas, Diagnostico e Plano ----------\nfunction compute(S) {\n  const N = S.negocio;\n  const negErros = validarNegocio(N);\n  const negOK = negErros.length === 0;\n  const matOK = N.maturidade.every(isNum);\n  const matMedia = matOK ? N.maturidade.reduce((a, b) => a + b, 0) / 4 : null;          // Negocio!B19\n  const teto = matOK ? (matMedia < 1 ? 1 : matMedia < 2 ? 2 : 3) : null;                 // Negocio!B20\n  const IV = N.intervencoes;\n  const idCount = (list, id) => list.filter(x => filled(x.id) && up(x.id) === up(id)).length;\n\n  // Equipe!L (situação do cadastro)\n  const equipe = S.equipe.map(p => {\n    const vazio = ![p.id, p.nome, p.funcao, p.gestor, p.prontidao].some(filled) && !p.c.some(isNum);\n    const erros = [];\n    if (!vazio) {\n      if (!filled(p.id)) erros.push('Informe o código.');\n      else if (idCount(S.equipe, p.id) !== 1) erros.push('Código repetido.');\n      if (!filled(p.nome)) erros.push('Informe o nome.');\n      if (!filled(p.funcao)) erros.push('Informe a função.');\n      if (p.gestor !== 'Sim' && p.gestor !== 'Não') erros.push('Indique se é gestor.');\n      if (!PRONTIDOES.includes(p.prontidao)) erros.push('Indique a faixa de prontidão.');\n      if (!p.c.every(isNum)) erros.push('Preencha as seis competências.');\n      else if (p.c.some(x => x < 0 || x > 3)) erros.push('Competências vão de 0 a 3.');\n    }\n    return { ...p, vazio, erros, ok: !vazio && erros.length === 0 };\n  });\n  const pessoaOK = id => equipe.filter(p => p.ok && up(p.id) === up(id));\n\n  // Tarefas!L:O (risco, classe inicial, classe final, situação)\n  const tarefas = S.tarefas.map(t => {\n    const vazio = ![t.id, t.nome, ...TASK_Q.map(k => t[k])].some(filled);\n    const erros = [];\n    if (!vazio) {\n      if (!filled(t.id)) erros.push('Informe o código.');\n      else if (idCount(S.tarefas, t.id) !== 1) erros.push('Código repetido.');\n      if (!filled(t.nome)) erros.push('Descreva a tarefa.');\n      if (TASK_Q.some(k => t[k] !== 'Sim' && t[k] !== 'Não')) erros.push('Responda Sim ou Não em todas as perguntas.');\n    }\n    const ok = !vazio && erros.length === 0;\n    let risco = null, inicial = null, final = null;\n    if (ok) {\n      risco = (t.r1 === 'Sim' ? 1 : 0) + (t.r2 === 'Sim' ? 1 : 0) + (t.r3 === 'Não' ? 1 : 0);\n      inicial = (t.q1 === 'Sim' || t.q2 === 'Sim') ? 'Humana'\n        : (t.q3 === 'Sim' && t.q4 === 'Sim') ? 'Automação'\n        : t.q5 === 'Sim' ? 'Colaboração' : 'Aumento';\n      final = (inicial === 'Automação' && isNum(N.riscoAlto) && risco >= N.riscoAlto) ? 'Aumento' : inicial;\n    }\n    return { ...t, vazio, erros, ok, risco, inicial, final };\n  });\n  const tarefaOK = id => tarefas.filter(t => t.ok && up(t.id) === up(id));\n\n  // Diagnostico!I:W — campos por diagnóstico\n  const diags = S.diagnosticos.map(d => {\n    const vazio = ![d.id, d.pessoa, d.tarefa, d.comp, d.andamento].some(filled) && !isNum(d.meta) && !isNum(d.crit);\n    const erros = [];\n    if (!vazio) {\n      if (!filled(d.id)) erros.push('Informe o código.');\n      else if (idCount(S.diagnosticos, d.id) !== 1) erros.push('Código repetido.');\n      if (!filled(d.pessoa)) erros.push('Escolha a pessoa.');\n      else if (pessoaOK(d.pessoa).length !== 1) erros.push('Pessoa inexistente ou com cadastro incompleto.');\n      if (!filled(d.tarefa)) erros.push('Escolha a tarefa.');\n      else if (tarefaOK(d.tarefa).length !== 1) erros.push('Tarefa inexistente ou incompleta.');\n      if (!COMPS.some(c => c[0] === d.comp)) erros.push('Escolha a competência.');\n      if (!isNum(d.meta) || d.meta < 0 || d.meta > 3) erros.push('Meta futura de 0 a 3.');\n      if (!isNum(d.crit) || d.crit < 1 || d.crit > 3) erros.push('Criticidade de 1 a 3.');\n      if (!ANDAMENTOS.includes(d.andamento)) erros.push('Escolha o andamento.');\n      if (filled(d.pessoa) && filled(d.tarefa) && filled(d.comp) &&\n        S.diagnosticos.filter(x => up(x.pessoa) === up(d.pessoa) && up(x.tarefa) === up(d.tarefa) && x.comp === d.comp).length !== 1)\n        erros.push('Combinação pessoa + tarefa + competência repetida.');\n      if (!negOK) erros.push('Corrija os parâmetros do Negócio.');\n    }\n    const ok = !vazio && erros.length === 0;\n    const r = { ...d, vazio, erros, ok, X: '', nec: '' };\n    if (!ok) { r.justificativa = vazio ? '' : 'Corrigir os campos de entrada'; return r; }\n\n    const p = pessoaOK(d.pessoa)[0], t = tarefaOK(d.tarefa)[0];\n    const ci = COMPS.findIndex(c => c[0] === d.comp);\n    Object.assign(r, {\n      pessoaId: p.id, pessoaNome: p.nome, gestor: p.gestor, tarefaNome: t.nome, compNome: COMPS[ci][1], ci,\n      classe: t.final, risco: t.risco, prontidao: p.prontidao, nivel: p.c[ci], teto,\n      ativa: t.ativa === 'Sim'\n    });\n    r.metaCiclo = Math.min(d.meta, teto);                       // S\n    r.lacunaFutura = Math.max(0, d.meta - r.nivel);             // T\n    r.lacunaCiclo = Math.max(0, r.metaCiclo - r.nivel);         // U\n    r.prioridade = r.lacunaCiclo * d.crit;                      // V\n    r.colegas = equipe.filter(o => o.ok && up(o.id) !== up(d.pessoa) && o.prontidao !== 'Baixa' && o.c[ci] === 3); // W\n    r.preservacao = (r.classe !== 'Humana' && r.risco >= N.riscoAlto) ? 'Registrar e praticar sem IA' : '';       // Z\n    r.bloqueadoMat = r.metaCiclo < d.meta && r.lacunaCiclo === 0 && r.lacunaFutura > 0;  // [v2-8] só o teto impede a ação\n    r.relevante = !(r.classe === 'Humana' || !r.ativa || d.andamento === 'Concluída');\n    // Necessidade do diagnóstico. [v2-2] prontidão baixa só gera preparação quando há lacuna;\n    // sem lacuna e com risco alto, a ação é preservação.\n    if (r.relevante) {\n      if (r.lacunaCiclo > 0) r.nec = p.prontidao === 'Baixa' ? 'CULT' : 'TEC';\n      else if (r.preservacao) r.nec = 'PRES';\n    }\n    return r;\n  });\n\n  // ---------- [v2-1] ações agrupadas ----------\n  const acoes = [];\n  const validos = diags.filter(d => d.ok);\n  const porId = id => S.equipe.find(p => up(p.id) === up(id));\n  const ordemDiag = (a, b) => cmpId(a.id, b.id);\n\n  // Treino técnico: uma ação por pessoa × competência (as tarefas viram contexto de prática)\n  const grupos = new Map();\n  for (const d of validos.filter(d => d.nec === 'TEC').sort(ordemDiag)) {\n    const k = up(d.pessoaId) + '|' + d.comp;\n    if (!grupos.has(k)) grupos.set(k, []);\n    grupos.get(k).push(d);\n  }\n  for (const ds of grupos.values()) {\n    const f = ds[0], p = equipe.find(o => up(o.id) === up(f.pessoaId));\n    const a = {\n      tipo: 'TEC', id: f.id, ids: ds.map(d => d.id), pessoa: f.pessoaId, pessoas: [f.pessoaId], pessoaNome: f.pessoaNome,\n      gestor: f.gestor === 'Sim', comp: f.comp, compNome: f.compNome, tarefaNome: ds.map(d => d.tarefaNome).join(' · '),\n      lacuna: Math.max(...ds.map(d => d.lacunaCiclo)), crit: Math.max(...ds.map(d => d.crit)),\n      prioridade: Math.max(...ds.map(d => d.prioridade)), risco: Math.max(...ds.map(d => d.risco)),\n      preservacao: ds.some(d => d.preservacao) ? 'Registrar e praticar sem IA' : '',\n      automacao: ds.some(d => d.classe === 'Automação'), colegas: f.colegas, prontidao: p.prontidao, nivelIA: p.c[0],\n      metaGradual: ds.some(d => d.metaCiclo < d.meta),\n      andamento: ds.some(d => d.andamento === 'Em andamento') ? 'Em andamento' : 'Não iniciada'\n    };\n    a.X = escolherIntervencao(a, IV, false);\n    if (a.X === 'PARES') a.alternativa = escolherIntervencao(a, IV, true);\n    acoes.push(a);\n  }\n\n  // [v2-1][v2-10] Preparação cultural: uma por pessoa; em grupo quando houver duas ou mais\n  const aguardando = [];\n  const precisaPrep = new Map();\n  for (const d of validos.filter(d => d.nec === 'CULT').sort(ordemDiag)) {\n    const k = up(d.pessoaId);\n    if (!precisaPrep.has(k)) precisaPrep.set(k, []);\n    precisaPrep.get(k).push(d);\n  }\n  const prepFeita = [], prepFazer = [];\n  for (const [k, ds] of precisaPrep) (porId(k).prep === 'Concluída' ? prepFeita : prepFazer).push(ds);\n  // [v2-4] preparação concluída e prontidão ainda baixa: aguardar a reaplicação da autoavaliação\n  for (const ds of prepFeita) aguardando.push({ pessoa: ds[0].pessoaId, pessoaNome: ds[0].pessoaNome, ids: ds.map(d => d.id) });\n  const montarPrep = lista => {\n    const ds = lista.flat(), membros = lista.map(l => l[0].pessoaId);\n    const facilitadores = equipe.filter(o => o.ok && o.prontidao !== 'Baixa' && !membros.some(m => up(m) === up(o.id)));\n    const n = membros.length;\n    acoes.push({\n      tipo: 'CULT', X: 'CULT', id: ds.map(d => d.id).sort(cmpId)[0], ids: ds.map(d => d.id).sort(cmpId), pessoa: n === 1 ? membros[0] : '', pessoas: membros,\n      pessoaNome: lista.map(l => l[0].pessoaNome).join(', '), gestor: ds.some(d => d.gestor === 'Sim'), comp: null, compNome: '',\n      tarefaNome: [...new Set(ds.map(d => d.tarefaNome))].join(' · '), prioridade: Math.max(...ds.map(d => d.prioridade)),\n      risco: Math.max(...ds.map(d => d.risco)), preservacao: ds.some(d => d.preservacao) ? 'Registrar e praticar sem IA' : '',\n      grupo: n > 1, horasExtra: (n - 1) * N.cultHoraExtra, colegas: facilitadores, apoioExterno: facilitadores.length === 0,\n      andamento: membros.some(m => porId(m).prep === 'Em andamento') ? 'Em andamento' : 'Não iniciada'\n    });\n  };\n  if (prepFazer.length) {\n    if (N.cultGrupo === 'Sim') montarPrep(prepFazer);\n    else prepFazer.forEach(l => montarPrep([l]));\n  }\n\n  // Preservação sem lacuna: uma por pessoa\n  const pres = new Map();\n  for (const d of validos.filter(d => d.nec === 'PRES').sort(ordemDiag)) {\n    const k = up(d.pessoaId);\n    if (!pres.has(k)) pres.set(k, []);\n    pres.get(k).push(d);\n  }\n  for (const ds of pres.values()) {\n    const f = ds[0];\n    acoes.push({\n      tipo: 'PRES', X: 'PRES', id: f.id, ids: ds.map(d => d.id), pessoa: f.pessoaId, pessoas: [f.pessoaId], pessoaNome: f.pessoaNome,\n      gestor: f.gestor === 'Sim', comp: f.comp, compNome: f.compNome, tarefaNome: [...new Set(ds.map(d => d.tarefaNome))].join(' · '),\n      prioridade: Math.max(...ds.map(d => d.crit)),   // [v2-5] prioridade pela criticidade, não zero\n      risco: Math.max(...ds.map(d => d.risco)), preservacao: 'Registrar e praticar sem IA', colegas: [],\n      andamento: ds.some(d => d.andamento === 'Em andamento') ? 'Em andamento' : 'Não iniciada'\n    });\n  }\n\n  // [v2-8] Maturidade digital: ação da loja quando o teto bloqueia alguém por completo (lacuna do ciclo 0,\n  // lacuna futura > 0) ou quando o teto é 1 (loja sem base digital)\n  const limitados = validos.filter(d => d.relevante && d.metaCiclo < d.meta && (d.bloqueadoMat || teto === 1));\n  const focoMat = matOK ? MATURIDADE_ITENS.filter((_, i) => N.maturidade[i] === Math.min(...N.maturidade)) : [];\n  if (matOK && teto < 3 && limitados.length && N.matAndamento !== 'Concluída') {\n    const gestor = equipe.find(p => p.ok && p.gestor === 'Sim');\n    acoes.push({\n      tipo: 'MAT', X: 'MAT', id: limitados.map(d => d.id).sort(cmpId)[0], ids: [], pessoa: gestor ? gestor.id : '', pessoas: gestor ? [gestor.id] : [],\n      pessoaNome: 'Loja' + (gestor ? ' (' + gestor.nome + ')' : ''), gestor: true, comp: null, compNome: '', tarefaNome: focoMat.join(' · '),\n      prioridade: Math.min(9, Math.max(...limitados.map(d => (d.meta - d.metaCiclo) * d.crit))), risco: 0, preservacao: '', colegas: [],\n      foco: focoMat, andamento: N.matAndamento === 'Em andamento' ? 'Em andamento' : 'Não iniciada'\n    });\n  }\n\n  const aplicarIV = a => {\n    const iv = IV[a.X];\n    a.intervencao = iv.nome;\n    a.horas = iv.horas + (a.horasExtra || 0) + (a.preservacao && a.X !== 'PRES' ? N.presHoras : 0) + (a.X === 'PRES' ? N.presHoras : 0);\n    a.semanas = Math.max(iv.semanas, a.preservacao ? 4 : 0);\n    a.custo = iv.custo;\n  };\n  acoes.forEach(aplicarIV);\n\n  // [v2-3] Ordem: prioridade; preparação cultural só desempata; depois gestor, risco, custo e código\n  acoes.sort((a, b) => b.prioridade - a.prioridade || (b.X === 'CULT') - (a.X === 'CULT') || b.gestor - a.gestor\n    || b.risco - a.risco || a.custo - b.custo || cmpId(a.id, b.id));\n\n  // Plano: admissão sequencial por horas, orçamento, vagas e carga dos colegas\n  let usoH = 0, usoC = 0, usoN = 0;\n  const pagos = new Set(), carga = {};\n  const plano = acoes.map((a, i) => {\n    // [v2-9] colega com menor carga; se todos estão no limite, usa a intervenção alternativa\n    if (a.X === 'PARES') {\n      const livre = a.colegas.filter(c => (carga[up(c.id)] || 0) < N.maxAprendizes)\n        .sort((x, y) => (carga[up(x.id)] || 0) - (carga[up(y.id)] || 0) || cmpId(x.id, y.id))[0];\n      if (livre) a.colega = livre;\n      else { a.trocaColega = `Colegas aptos já com ${N.maxAprendizes} aprendizes`; a.X = a.alternativa; aplicarIV(a); }\n    }\n    const custoEf = IV[a.X].compartilhado && pagos.has(a.X) ? 0 : a.custo;   // [v2-12]\n    const consomeVaga = a.X !== 'PRES';                                         // [v2-5]\n    const cabeH = usoH + a.horas <= N.horas + EPS;\n    const cabeC = usoC + custoEf <= N.orcamento + EPS;\n    const cabeN = !consomeVaga || usoN < N.maxAcoes;\n    const admitida = negOK && cabeH && cabeC && cabeN;\n    a.justificativa = justificar(a);\n    const motivo = admitida ? a.justificativa\n      : !cabeH ? 'Horas semanais insuficientes' : !cabeC ? 'Orçamento insuficiente' : 'Limite de ações simultâneas';\n    if (admitida) {\n      usoH += a.horas; usoC += custoEf; if (consomeVaga) usoN++;\n      if (IV[a.X].compartilhado) pagos.add(a.X);\n      if (a.X === 'PARES') carga[up(a.colega.id)] = (carga[up(a.colega.id)] || 0) + 1;\n    }\n    a.custoEfetivo = custoEf;\n    const prazo = !admitida ? 'Próximo ciclo' : a.X === 'CULT' ? 'Preparação cultural' : a.semanas <= 4 ? '0-30 dias' : '31-90 dias';\n    return { ordem: i + 1, d: a, admitida, motivo, prazo, saldo: (N.horas || 0) - usoH };\n  });\n\n  function justificar(a) {\n    if (a.X === 'CULT') return a.apoioExterno ? 'Sem colega com prontidão moderada ou alta: preparação com apoio externo'\n      : a.grupo ? 'Conversa em grupo; reaplicar a autoavaliação antes do treino' : 'Preparar e reaplicar prontidão antes do treino';\n    if (a.X === 'PRES') return 'Preservar competência mesmo sem lacuna';\n    if (a.X === 'MAT') return 'Elevar a maturidade digital (foco: ' + a.foco.join(', ') + ')';\n    if (a.X === 'EXT') return 'Sem colega apto na loja: buscar apoio externo (fornecedor, curso, Sebrae)';\n    if (a.X === 'PARES') return a.colega ? 'Combinar agenda com ' + a.colega.nome : 'Escolher colega nível 3 e combinar agenda';\n    if (a.metaGradual) return 'Meta gradual limitada pela maturidade';\n    return 'Desenvolver a lacuna com recursos existentes';\n  }\n\n  // devolve a ação de cada diagnóstico (para a tela de Diagnóstico)\n  for (const d of diags.filter(d => d.ok)) {\n    const a = acoes.find(x => x.ids.includes(d.id));\n    if (a) Object.assign(d, { X: a.X, acao: a.id, intervencao: a.intervencao, horas: a.horas, semanas: a.semanas, custo: a.custo });\n    d.justificativa = d.andamento === 'Concluída' ? 'Atualizar nível e evidência na reavaliação'\n      : !d.ativa ? 'Tarefa inativa'\n      : d.classe === 'Humana' ? 'Manter responsabilidade humana'\n      : a ? a.justificativa + (a.ids.length > 1 ? ` (ação ${a.id}, junto com ${a.ids.filter(x => x !== d.id).join(', ')})` : '')\n      : d.nec === 'CULT' ? 'Aguardando reavaliação da prontidão'\n      : d.bloqueadoMat ? `Bloqueado pela maturidade digital (lacuna futura ${d.lacunaFutura})`\n      : 'Sem lacuna no ciclo';\n  }\n\n  const pend = {\n    negocio: negErros.length,\n    equipe: equipe.filter(p => !p.vazio && !p.ok).length,\n    tarefas: tarefas.filter(t => !t.vazio && !t.ok).length,\n    diagnosticos: diags.filter(d => !d.vazio && !d.ok).length\n  };\n  const temPend = pend.negocio + pend.equipe + pend.tarefas + pend.diagnosticos > 0;\n  const noCiclo = plano.filter(x => x.admitida).length;\n  const adiadas = plano.length - noCiclo;\n\n  // [v2-7] pontos de atenção\n  const alertas = [];\n  for (const p of plano.filter(p => p.d.X === 'CULT' && p.d.apoioExterno))\n    alertas.push(`Preparação cultural de ${p.d.pessoaNome}: não há colega com prontidão moderada ou alta para conduzir; buscar apoio externo.`);\n  const ext = plano.filter(p => p.d.X === 'EXT');\n  if (ext.length) alertas.push(`Apoio externo necessário para ${ext.map(p => p.d.pessoaNome).join(', ')}: ninguém na loja tem nível 3 e a mentoria por IA não é indicada.`);\n  if (aguardando.length) alertas.push(`Reaplicar a autoavaliação de ${aguardando.map(a => a.pessoaNome).join(', ')}: preparação cultural concluída.`);\n\n  const soPres = plano.length > 0 && plano.every(p => p.d.X === 'PRES');\n  const situacao = temPend ? { tipo: 'erro', texto: 'Há entradas pendentes: corrija os campos sinalizados antes de usar o plano.' }   // Plano!A7\n    : plano.length === 0 ? { tipo: 'aviso', texto: aguardando.length ? alertas[alertas.length - 1] : 'Sem ações: confira tarefas ativas, lacunas, risco e ações concluídas.' }\n    : N.horas === 0 ? { tipo: 'aviso', texto: 'Sem horas disponíveis: negociar tempo para capacitação.' }\n    : adiadas > 0 ? { tipo: 'aviso', texto: 'Há ações adiadas: confira horas, orçamento e limite simultâneo.' }\n    : alertas.length ? { tipo: 'aviso', texto: 'Plano calculado, com pontos de atenção: ' + alertas.join(' ') }\n    : soPres ? { tipo: 'ok', texto: 'Equipe sem lacunas no ciclo: manter a preservação nas tarefas de risco alto.' }\n    : { tipo: 'ok', texto: 'Plano calculado. Confirmar agenda e participação com a equipe.' };\n\n  return {\n    negErros, negOK, matMedia, teto, reavaliacao: addDays(N.dataBase, 90),\n    equipe, tarefas, diags, plano, pend, situacao, alertas, aguardando,\n    resumo: { noCiclo, adiadas, horas: usoH, custo: usoC, vagas: usoN, necessarias: plano.length }\n  };\n}\n\n// [v2-4] registrar andamento de uma ação do plano (usado pela tela e pelos testes)\nfunction concluirAcao(S, a, valor) {\n  if (a.X === 'CULT') a.pessoas.forEach(id => { const p = S.equipe.find(x => up(x.id) === up(id)); if (p) p.prep = valor === 'Não iniciada' ? '' : valor; });\n  else if (a.X === 'MAT') S.negocio.matAndamento = valor;\n  else S.diagnosticos.filter(d => a.ids.includes(d.id)).forEach(d => d.andamento = valor);\n}\n// [v2-4] nova autoavaliação reabre o ciclo de preparação da pessoa\nfunction aplicarAutoavaliacao(p, res) {\n  p.prontidao = res.prontidao;\n  p.c = COMPS.map(c => res.competencias[c[0]]);\n  p.prep = '';\n}\n\n// ---------- autoavaliação do colaborador ----------\nconst PERGUNTAS = [\n  'Consigo aprender a usar uma ferramenta de IA com orientação.',\n  'Consigo reconhecer quando preciso de ajuda ao usar IA.',\n  'Minha liderança oferece apoio para aprender novas formas de trabalho.',\n  'Tenho espaço para conversar sobre dúvidas e dificuldades com a mudança.',\n  'A possibilidade de usar IA no trabalho me deixa ansioso(a).',\n  'O medo de errar com IA me impede de experimentar novas tarefas.',\n  'Estou disposto(a) a testar novas formas de realizar minhas tarefas.',\n  'Estou disposto(a) a aprender com colegas e compartilhar o que aprendo.'\n];\nfunction calcularAutoavaliacao(id, skills, answers, low = 1, high = 2, simulated = false) {\n  if (!String(id).trim() || skills.length !== 6 || answers.length !== 8) throw new Error('Preencha o código, as 6 competências e as 8 perguntas.');\n  if (![...skills, ...answers].every(x => Number.isInteger(x) && x >= 0 && x <= 3)) throw new Error('Cada resposta deve ser um número inteiro entre 0 e 3.');\n  if (!Number.isFinite(low) || !Number.isFinite(high) || low < 0 || high > 3 || high <= low) throw new Error('Os limites devem satisfazer 0 ≤ baixa < alta ≤ 3.');\n  const avg = answers.reduce((s, x, i) => s + ([4, 5].includes(i) ? 3 - x : x), 0) / 8;   // itens 5 e 6 invertidos\n  let band = avg < low ? 'Baixa' : avg < high ? 'Moderada' : 'Alta';\n  // [v2-11] medo e ansiedade no máximo: faixa baixa; um dos dois no máximo: no máximo moderada\n  if (answers[4] === 3 && answers[5] === 3) band = 'Baixa';\n  else if ((answers[4] === 3 || answers[5] === 3) && band === 'Alta') band = 'Moderada';\n  const alertas = answers.every(x => x === answers[0]) ? ['Todas as respostas de prontidão iguais: confirmar a faixa em conversa.'] : [];\n  return {\n    versao: '2.0', codigo: String(id).trim(), origem: simulated ? 'Demonstração simulada' : 'Autoavaliação individual',\n    prontidao: band, competencias: Object.fromEntries(COMPS.map((c, i) => [c[0], skills[i]])),\n    limites: { baixa_menor_que: low, alta_a_partir_de: high }, alertas\n  };\n}\n\n// textos.js\n// Rótulos exibidos na tela, com a terminologia da planilha Matriz_Transicao_IA_v1.xlsx\n// (abas Guia, Negocio, Equipe, Tarefas, Diagnostico e Plano) e do formulário do colaborador.\n\n// Escala de competência (Guia!A16:B19)\nconst NIVEIS_TXT = [\n  ['0 · Não utiliza', ''],\n  ['1 · Executa com apoio', ''],\n  ['2 · Executa com autonomia', ''],\n  ['3 · Executa com autonomia e ensina', '']\n];\n\n// Competências C01 a C06 (Guia!A22:C27): nome e grupo\nconst HABILIDADES = Object.fromEntries(COMPS.map(c => [c[0], [c[0] + ' · ' + c[1], c[2]]]));\n\n// Faixas de prontidão e orientação do formulário original\nconst PRONTIDAO_TXT = {\n  Baixa: ['Prontidão baixa', 'Antes do treino técnico, combine uma conversa e uma demonstração com um colega. Repita a coleta depois da preparação.'],\n  Moderada: ['Prontidão moderada', 'Comece com apoio e prática acompanhada. Combine dúvidas e expectativas com a liderança.'],\n  Alta: ['Prontidão alta', 'A faixa permite iniciar aprendizagem planejada, conforme as lacunas e o tempo disponível.']\n};\n\n// Criticidade (Guia!C16:C19)\nconst IMPORTANCIA_TXT = { 1: ['1 · Baixa', 'Efeito limitado'], 2: ['2 · Média', 'Afeta a rotina'], 3: ['3 · Alta', 'Essencial à operação'] };\n\n// Classe final da tarefa (Tarefas!N)\nconst CLASSE_TXT = {\n  'Humana': ['Humana', 'Q1 ou Q2: a tarefa permanece humana e não gera capacitação para IA.'],\n  'Automação': ['Automação', 'Regras claras e decisão delegável (Q3 + Q4).'],\n  'Aumento': ['Aumento', 'IA apoia, pessoa decide.'],\n  'Colaboração': ['Colaboração', 'Pessoa e IA refinam sugestões em conjunto.']\n};\n\n// Catálogo de intervenções (Negocio!A30:B35)\nconst INTERVENCAO_TXT = {\n  CULT: ['Preparação cultural', 'Conversa e demonstração com um colega antes do treino técnico, uma por pessoa (em grupo quando houver mais de uma). Reaplicar o formulário de prontidão depois da preparação.'],\n  PARES: ['Aprendizagem entre pares', 'Colega com nível 3 na competência, prontidão moderada ou alta, ensina na rotina.'],\n  EXP: ['Experimentação assistida', 'Prática acompanhada com a ferramenta; compatível com lacuna do ciclo ≥ 2 ou prontidão moderada.'],\n  TUTOR: ['Mentoria por IA', 'Aprendizagem com assistente de IA; para prontidão alta e quem já usa IA (C01 ≥ 1), com lacuna 1 ou sem colega apto.'],\n  RED: ['Redesenho gradual', 'Transição gradual de tarefa classificada como Automação.'],\n  PRES: ['Preservação de competências', 'Documentar a rotina e praticar sem IA; obrigatória com risco alto, mesmo sem lacuna. Não ocupa vaga de ação simultânea.'],\n  EXT: ['Apoio externo', 'Curso, fornecedor da ferramenta ou instituição de apoio (ex.: Sebrae) quando nenhuma opção interna é compatível (sem colega nível 3 e mentoria por IA não indicada).'],\n  MAT: ['Elevar maturidade digital', 'Ação da loja: organizar registros, equipamentos, rotinas de conferência e apoio à aprendizagem. Indicada quando a maturidade bloqueia o desenvolvimento.']\n};\n\nconst ANDAMENTO_TXT = { 'Não iniciada': 'Não iniciada', 'Em andamento': 'Em andamento', 'Concluída': 'Concluída' };\nconst PRAZO_TXT = { 'Preparação cultural': 'Preparação cultural', '0-30 dias': '0-30 dias', '31-90 dias': '31-90 dias', 'Próximo ciclo': 'Próximo ciclo' };\nconst MOTIVO_TXT = {\n  'Horas semanais insuficientes': 'Horas semanais insuficientes',\n  'Orçamento insuficiente': 'Orçamento insuficiente',\n  'Limite de ações simultâneas': 'Limite de ações simultâneas'\n};\n// Justificativas (Diagnostico!AG) exibidas sem alteração\nconst PROXIMO_PASSO_TXT = {};\n\n// Perguntas guiadas (Tarefas!C6:K6)\nconst PERGUNTAS_TAREFA = [\n  ['ativa', 'Ativa?', 'A tarefa faz parte da rotina atual?'],\n  ['q1', 'Q1 · Exige presença física?', ''],\n  ['q2', 'Q2 · Exige empatia ou negociação?', ''],\n  ['q3', 'Q3 · Segue regras claras?', ''],\n  ['q4', 'Q4 · A decisão pode ser delegada?', ''],\n  ['q5', 'Q5 · Há troca de ideias com a IA?', ''],\n  ['r1', 'R1 · O saber está concentrado em poucas pessoas?', ''],\n  ['r2', 'R2 · Um erro causa prejuízo?', ''],\n  ['r3', 'R3 · A equipe pratica a tarefa sem IA?', '']\n];\n\nconst SUGESTOES_TAREFAS = [\n  'Responder dúvidas no WhatsApp', 'Planejar pedido ao fornecedor', 'Criar conteúdo para redes sociais',\n  'Conferir lançamentos do caixa', 'Negociar reclamação sensível', 'Analisar indicadores de vendas',\n  'Preparar roteiro de capacitação', 'Conferir produtos na prateleira', 'Controlar estoque', 'Definir preços e promoções'\n];\n\n// Maturidade digital (Negocio!A13:A17)\nconst MATURIDADE_PERGUNTAS = [\n  ['Registros digitais organizados'],\n  ['Equipamentos e acesso disponíveis'],\n  ['Rotinas de conferência de dados'],\n  ['Apoio à aprendizagem na rotina']\n];\nconst MATURIDADE_ESCALA = [['0 · Ausente', ''], ['1 · Inicial', ''], ['2 · Regular', ''], ['3 · Consolidada', '']];\n\n// Escala de prontidão do formulário\nconst QUESTIONARIO_ESCALA = ['0 · Discordo totalmente', '1 · Discordo', '2 · Concordo', '3 · Concordo totalmente'];\n\n// util.js\n// Peças reutilizáveis da interface: criação de elementos, formatação, escolhas em botões,\n// contador com − e +, janelas e downloads.\n\nfunction h(tag, props, ...kids) {\n  const e = document.createElement(tag);\n  for (const [k, v] of Object.entries(props || {})) {\n    if (v === null || v === undefined || v === false) continue;\n    if (k === 'class') e.className = v;\n    else if (k.startsWith('on') && typeof v === 'function') e.addEventListener(k.slice(2), v);\n    else if (k === 'value' || k === 'checked' || k === 'disabled' || k === 'hidden') e[k] = v;\n    else e.setAttribute(k, v === true ? '' : v);\n  }\n  for (const c of kids.flat(Infinity)) if (c !== null && c !== undefined && c !== false) e.append(c.nodeType ? c : String(c));\n  return e;\n}\nconst esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst fmtN = x => isNum(x) ? x.toLocaleString('pt-BR', { maximumFractionDigits: 2 }) : '—';\nconst fmtH = x => isNum(x) ? fmtN(x) + ' h' : '—';\nconst fmtR = x => isNum(x) ? x.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : '—';\nconst fmtD = iso => iso ? iso.split('-').reverse().join('/') : '—';\nconst hoje = () => new Date().toISOString().slice(0, 10);\nconst plural = (n, um, varios) => n === 1 ? `1 ${um}` : `${n} ${varios}`;\nconst uid = () => Math.random().toString(36).slice(2, 9);\n\n// Acrescenta filhos ignorando vazios e achatando listas (o append nativo escreveria \"null\" ou \"[object HTMLElement]\")\nfunction put(el, ...kids) { for (const c of kids.flat(Infinity)) if (c !== null && c !== undefined && c !== false && c !== '') el.append(c.nodeType ? c : String(c)); return el; }\n\n// Implementações de cada tela (preenchidas pelos arquivos em telas/)\nconst V = {};\n\nfunction toast(msg) {\n  const t = document.getElementById('toast');\n  t.textContent = msg; t.classList.add('show');\n  clearTimeout(toast.timer); toast.timer = setTimeout(() => t.classList.remove('show'), 4200);\n}\nfunction baixar(nome, conteudo, tipo) {\n  const url = URL.createObjectURL(new Blob([conteudo], { type: tipo }));\n  const a = h('a', { href: url, download: nome, hidden: true });\n  document.body.append(a); a.click();\n  setTimeout(() => { a.remove(); URL.revokeObjectURL(url); }, 1500);\n}\nfunction abrirArquivo(accept, cb) {\n  const inp = h('input', { type: 'file', accept, hidden: true });\n  inp.addEventListener('change', () => {\n    const f = inp.files[0]; if (!f) return;\n    const r = new FileReader();\n    r.onload = () => { try { cb(r.result, f.name); } catch (e) { toast(e.message); } inp.remove(); };\n    r.readAsText(f, 'utf-8');\n  });\n  document.body.append(inp); inp.click();\n}\nconst nomeArquivo = s => String(s || 'arquivo').normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '');\n\n// Escolha única em botões grandes (rádios por baixo, para teclado e leitores de tela).\n// opcoes: [[valor, rótulo, descrição?], ...]\nfunction escolha(opcoes, valor, aoMudar, { cols = false, nome } = {}) {\n  const grupo = nome || 'g' + uid();\n  const wrap = h('div', { class: 'choices' + (cols ? ' cols' : ''), role: 'radiogroup' });\n  for (const [v, rot, desc] of opcoes) {\n    const inp = h('input', { type: 'radio', name: grupo, value: String(v), checked: valor !== null && valor !== undefined && String(valor) === String(v) });\n    inp.addEventListener('change', () => aoMudar(v));\n    wrap.append(h('label', { class: 'choice' }, inp, h('span', {}, rot, desc ? h('small', {}, desc) : null)));\n  }\n  return wrap;\n}\nconst simNao = (valor, aoMudar) => escolha([['Sim', 'Sim'], ['Não', 'Não']], valor, aoMudar);\n\n// Contador com botões − e +\nfunction contador(valor, aoMudar, { passo = 1, min = 0, max = 9999, unidade = '', rotulo } = {}) {\n  const inp = h('input', { type: 'number', inputmode: 'decimal', value: valor ?? '', min, max, step: passo, 'aria-label': rotulo });\n  const definir = v => {\n    v = Math.min(max, Math.max(min, Math.round(v / passo) * passo));\n    inp.value = v; aoMudar(v);\n  };\n  inp.addEventListener('input', () => { const t = inp.value.replace(',', '.'); if (t === '') return aoMudar(null); const n = Number(t); if (Number.isFinite(n)) aoMudar(n); });\n  inp.addEventListener('blur', () => { if (inp.value !== '') definir(Number(inp.value)); });\n  return h('div', { class: 'stepper' },\n    h('button', { type: 'button', 'aria-label': 'Diminuir', onclick: () => definir((Number(inp.value) || 0) - passo) }, '−'),\n    inp,\n    unidade ? h('span', { class: 'unit' }, unidade) : null,\n    h('button', { type: 'button', 'aria-label': 'Aumentar', onclick: () => definir((Number(inp.value) || 0) + passo) }, '+'));\n}\n\nfunction texto(valor, aoMudar, attrs = {}) {\n  return h('input', { class: 'in', type: 'text', value: valor ?? '', placeholder: attrs.placeholder, maxlength: attrs.maxlength || 80, oninput: e => aoMudar(e.target.value) });\n}\n\n// Bloco \"pergunta + resposta\"\nfunction campo(pergunta, controle, dica) {\n  const id = 'c' + uid();\n  const temLabel = controle.matches && controle.matches('input, select, textarea');\n  if (temLabel) controle.id = id;\n  return h('div', { class: 'field' },\n    temLabel ? h('label', { for: id }, pergunta) : h('div', { class: 'q' }, pergunta),\n    dica ? h('span', { class: 'hint' }, dica) : null,\n    controle);\n}\n\nfunction cabecalho(titulo, textoApoio) {\n  return h('header', { class: 'head' }, h('h1', {}, titulo), textoApoio ? h('p', {}, textoApoio) : null);\n}\n\nfunction bolinhas(n) {\n  const v = isNum(n) ? n : 0;\n  return h('span', { class: 'dots', 'aria-label': isNum(n) ? NIVEIS_TXT[n][0] : 'não informado' }, '●'.repeat(v), h('i', {}, '●'.repeat(3 - v)));\n}\n\n// Janela (dialog). conteudo(corpo, rodape) monta o miolo; acoes = [{texto, classe, aoClicar}] onde aoClicar devolve true para fechar.\nfunction janela({ titulo, subtitulo, montar, botaoOk = 'Salvar', aoConfirmar, larga }) {\n  const msg = h('span', { class: 'dlg-msg', role: 'alert' });\n  const corpo = h('div', { class: 'dlg-body' });\n  const dlg = h('dialog', { 'aria-label': titulo, style: larga ? 'width:min(880px,calc(100vw - 24px))' : null });\n  const fechar = () => { dlg.close(); dlg.remove(); };\n  const ok = h('button', { class: 'btn', type: 'button', onclick: () => {\n    msg.textContent = '';\n    try { if (aoConfirmar() !== false) fechar(); } catch (e) { msg.textContent = e.message; }\n  } }, botaoOk);\n  const rodape = h('div', { class: 'dlg-foot' }, msg, h('button', { class: 'btn light', type: 'button', onclick: fechar }, 'Cancelar'), aoConfirmar ? ok : null);\n  dlg.append(h('div', { class: 'dlg' },\n    h('div', { class: 'dlg-head' }, h('div', {}, h('h2', {}, titulo), subtitulo ? h('p', {}, subtitulo) : null),\n      h('button', { class: 'dlg-x', type: 'button', 'aria-label': 'Fechar', onclick: fechar }, '×')),\n    corpo, rodape));\n  dlg.addEventListener('cancel', e => { e.preventDefault(); fechar(); });\n  document.body.append(dlg);\n  const api = { corpo, rodape, ok, msg, fechar, erro: t => { msg.textContent = t; } };\n  montar(corpo, api);\n  dlg.showModal();\n  corpo.scrollTop = 0;\n  return api;\n}\n\n// formulario.js\n// Autoavaliação individual: competências atuais e prontidão para a mudança.\n// É usado de dois jeitos: dentro da tela do gerente e no arquivo entregue a cada pessoa.\n\nfunction questionario({ nome, pedirNome = false, voce = false, low = 1, high = 2, exemplo = false, onMudou }) {\n  const resp = { nome: nome || '', skills: Array(6).fill(null), answers: Array(8).fill(null) };\n  const blocos = { skills: [], answers: [] };\n  const el = h('div');\n  const mudou = () => onMudou && onMudou();\n\n  if (pedirNome) {\n    const nomeIn = texto('', v => { resp.nome = v; mudou(); }, { placeholder: 'Ex.: Bruno' });\n    put(el, h('div', { class: 'block' }, campo('Seu nome', nomeIn, 'Use o mesmo nome cadastrado na Equipe. Evite outros dados pessoais.')));\n    blocos.nome = nomeIn;\n  }\n\n  const parte1 = h('div', { class: 'block' }, h('h2', {}, 'Competências atuais'),\n    h('p', { class: 'lead' }, '0 = não utiliza · 1 = executa com apoio · 2 = executa com autonomia · 3 = executa e ensina colegas.'));\n  COMPS.forEach((c, i) => {\n    const [titulo, desc] = HABILIDADES[c[0]];\n    const f = campo(titulo, escolha(NIVEIS_TXT.map((n, j) => [j, n[0], n[1]]), null, v => { resp.skills[i] = v; f.classList.remove('missing'); mudou(); }, { cols: true }), desc);\n    blocos.skills.push(f); put(parte1, f);\n  });\n\n  const parte2 = h('div', { class: 'block' }, h('h2', {}, 'Prontidão para a mudança'),\n    h('p', { class: 'lead' }, '0 = discordo totalmente · 1 = discordo · 2 = concordo · 3 = concordo totalmente. Os itens sobre ansiedade têm pontuação invertida. Instrumento experimental de apoio à conversa, sem validação psicométrica.'));\n  PERGUNTAS.forEach((q, i) => {\n    const f = campo(q, escolha(QUESTIONARIO_ESCALA.map((t, j) => [j, t]), null, v => { resp.answers[i] = v; f.classList.remove('missing'); mudou(); }));\n    blocos.answers.push(f); put(parte2, f);\n  });\n  put(el, parte1, parte2);\n\n  if (exemplo) el.prepend(h('p', { class: 'small' }, h('button', { class: 'btn quiet', type: 'button', onclick: () => {\n    // respostas fictícias do Bruno (cenário Mercado Aurora)\n    const marcar = (lista, valores) => lista.forEach((f, i) => { const r = f.querySelector(`input[value=\"${valores[i]}\"]`); r.checked = true; r.dispatchEvent(new Event('change')); });\n    marcar(blocos.skills, [0, 1, 1, 3, 1, 0]); marcar(blocos.answers, [0, 1, 1, 1, 3, 3, 1, 0]);\n  } }, 'Preencher exemplo de Bruno')));\n\n  return {\n    el,\n    // devolve o resultado ou lança erro explicando o que falta, destacando a primeira pergunta sem resposta\n    resultado(codigo) {\n      const nomeFinal = (resp.nome || '').trim();\n      if (pedirNome && !nomeFinal) { blocos.nome.classList.add('bad'); blocos.nome.focus(); throw new Error('Preencha o nome.'); }\n      const faltando = [...blocos.skills.filter((f, i) => resp.skills[i] === null), ...blocos.answers.filter((f, i) => resp.answers[i] === null)];\n      faltando.forEach(f => f.classList.add('missing'));\n      if (faltando.length) { faltando[0].scrollIntoView({ behavior: 'smooth', block: 'center' }); throw new Error('Responda todos os itens antes de gerar o resultado.'); }\n      const r = calcularAutoavaliacao(codigo || nomeFinal, resp.skills, resp.answers, low, high, exemplo && resp.skills.join() === '0,1,1,3,1,0');\n      r.nome = nomeFinal || nome || '';\n      return r;\n    }\n  };\n}\n\n// Quadro com o resultado (não mostra as 8 respostas individuais)\nfunction quadroResultado(r, voce = false) {\n  const [faixa, explica] = PRONTIDAO_TXT[r.prontidao];\n  return h('div', {},\n    h('p', { class: 'muted', style: 'margin:0' }, 'Resultado para compartilhar' + (r.nome ? ' · ' + r.nome : '')),\n    h('p', { class: 'result-band' }, faixa),\n    h('p', { style: 'margin-top:0' }, explica),\n    (r.alertas || []).map(a => h('p', { class: 'status info', style: 'margin:8px 0' }, a)),\n    h('div', { class: 'skills block', style: 'padding:16px 18px;margin:12px 0' },\n      COMPS.map(c => h('div', {}, h('span', {}, HABILIDADES[c[0]][0]), h('span', {}, NIVEIS_TXT[r.competencias[c[0]]][0], ' ', bolinhas(r.competencias[c[0]]))))),\n    h('p', { class: 'small muted' }, 'Respostas individuais de prontidão não são incluídas no resultado nem na impressão.'));\n}\n\n// ---------- arquivo entregue a cada pessoa ----------\nfunction montarColaborador() {\n  const ds = document.documentElement.dataset;\n  const nome = ds.nome || '';\n  const low = Number(ds.low ?? 1), high = Number(ds.high ?? 2);\n  document.title = 'Autoavaliação individual' + (nome ? ' · ' + nome : '');\n  const q = questionario({ nome, pedirNome: !nome, voce: true, low, high });\n  const saida = h('div');\n  const botao = h('button', { class: 'btn big', type: 'button', onclick: () => {\n    aviso.textContent = '';\n    let r;\n    try { r = q.resultado(ds.codigo); } catch (e) { aviso.textContent = e.message; return; }\n    const arquivo = `Resposta_${nomeArquivo(r.nome || r.codigo)}.json`;\n    saida.replaceChildren(h('div', { class: 'block', style: 'border:2px solid var(--green)' },\n      h('h2', {}, 'Resultado gerado'),\n      h('p', { class: 'lead' }, 'Baixe o resultado e entregue o arquivo à liderança. O arquivo contém o código, a faixa de prontidão e os níveis de competências.'),\n      h('div', { class: 'actions' }, h('button', { class: 'btn big', type: 'button', onclick: () => {\n        baixar(arquivo, JSON.stringify(r, null, 2), 'application/json;charset=utf-8');\n        toast(`Resultado salvo como “${arquivo}”.`);\n      } }, 'Baixar resultado (.json)')),\n      h('p', { class: 'small muted' }, `Arquivo: “${arquivo}”.`),\n      h('hr', { style: 'border:0;border-top:1px dashed var(--line);margin:18px 0' }),\n      quadroResultado(r, true),\n      h('p', { class: 'small muted' }, 'Se o navegador não baixar arquivos, mostre esta tela à liderança para transcrição. Ao concluir, feche a página.')));\n    saida.scrollIntoView({ behavior: 'smooth', block: 'start' });\n  } }, 'Gerar meu resultado');\n  const aviso = h('p', { role: 'alert', style: 'color:var(--alert);font-weight:700' });\n  document.getElementById('root').append(h('div', { class: 'solo' },\n    cabecalho('Como você se prepara para trabalhar com IA?', (nome ? (ds.codigo ? ds.codigo + ' · ' : '') + nome + '. ' : '') + 'Uma autoavaliação para orientar aprendizagem e conversar sobre a mudança no pequeno varejo.'),\n    h('div', { class: 'privacy' }, 'As respostas de prontidão são processadas apenas nesta página. O arquivo de resultado contém seu código, a faixa de prontidão e os níveis de competências. Não inclui as oito respostas individuais.'),\n    q.el, aviso, botao, saida));\n}\n\nmontarColaborador();\n</script>\n</body>\n</html>\n";
